902	            if let Some(behavior) = registry.get(dead_card_id) {
903	                behavior.on_dies(state, dead_id, registry);
904	            }
905	        }
906	        PendingTrigger::DeathWatch { watcher_id, watcher_card_id, dead_id, dead_controller, dead_damaged_by, dead_toughness, .. } => {
907	            // Verify the watcher is still on the battlefield.
908	            if state.get_object(watcher_id).map(|o| o.zone == Zone::Battlefield).unwrap_or(false) {
909	                if let Some(behavior) = registry.get(watcher_card_id) {
910	                    behavior.on_any_creature_dies(state, watcher_id, dead_id, dead_controller, &dead_damaged_by, dead_toughness, registry);
911	                }
912	            }
913	        }
914	        PendingTrigger::EnterWatch { watcher_id, watcher_card_id, entered_id, entered_controller, .. } => {
915	            if state.get_object(watcher_id).map(|o| o.zone == Zone::Battlefield).unwrap_or(false) {
916	                if let Some(behavior) = registry.get(watcher_card_id) {
917	                    behavior.on_any_creature_enters(state, watcher_id, entered_id, entered_controller, registry);
